{"file_path":"src/heap.js","content":"/**
 * Binary min-heap with an index from key to position, supporting O(log n)
 * push, pop, remove, decreaseKey, and setPriority, and O(1) has, peek, and
 * priorityOf.
 */
export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} */
  #index = new Map();

  /** @type {number} */
  #nextSeq = 0;

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Validates that a key is a string.
   * @param {unknown} key Key to validate.
   * @returns {void}
   */
  #checkKey(key) {
    if (typeof key !== 'string') throw new TypeError('key must be a string');
  }

  /**
   * Validates that a priority is a finite number.
   * @param {unknown} priority Priority to validate.
   * @returns {void}
   */
  #checkPriority(priority) {
    if (typeof priority !== 'number' || !Number.isFinite(priority)) {
      throw new TypeError('priority must be a finite number');
    }
  }

  /**
   * Compares two entries by priority, then insertion order.
   * @param {{priority: number, seq: number}} a First entry.
   * @param {{priority: number, seq: number}} b Second entry.
   * @returns {boolean} True when a should sit above (be an ancestor of) b.
   */
  #less(a, b) {
    if (a.priority !== b.priority) return a.priority < b.priority;
    return a.seq < b.seq;
  }

  /**
   * Swaps two positions in the heap array, keeping the index in sync.
   * @param {number} i First position.
   * @param {number} j Second position.
   * @returns {void}
   */
  #swap(i, j) {
    const items = this.#items;
    [items[i], items[j]] = [items[j], items[i]];
    this.#index.set(items[i].key, i);
    this.#index.set(items[j].key, j);
  }

  /**
   * Moves the entry at a position up while it is smaller than its parent.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftUp(pos) {
    const items = this.#items;
    let i = pos;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.#less(items[i], items[parent])) {
        this.#swap(i, parent);
        i = parent;
      } else break;
    }
  }

  /**
   * Moves the entry at a position down while it is larger than a child.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftDown(pos) {
    const items = this.#items;
    const n = items.length;
    let i = pos;
    for (;;) {
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      let smallest = i;
      if (left < n && this.#less(items[left], items[smallest])) smallest = left;
      if (right < n && this.#less(items[right], items[smallest])) smallest = right;
      if (smallest === i) break;
      this.#swap(i, smallest);
      i = smallest;
    }
  }

  /**
   * Removes the entry at a given position, keeping the heap valid.
   * @param {number} pos Position to remove.
   * @returns {void}
   */
  #removeAt(pos) {
    const items = this.#items;
    const last = items.length - 1;
    const removedKey = items[pos].key;
    this.#index.delete(removedKey);
    if (pos !== last) {
      const moved = items[last];
      items[pos] = moved;
      this.#index.set(moved.key, pos);
      items.pop();
      this.#siftDown(pos);
      this.#siftUp(pos);
    } else {
      items.pop();
    }
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
  push(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    if (this.#index.has(key)) throw new Error(`duplicate key: "${key}"`);
    const entry = { key, priority, seq: this.#nextSeq };
    this.#nextSeq += 1;
    const pos = this.#items.length;
    this.#items.push(entry);
    this.#index.set(key, pos);
    this.#siftUp(pos);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    if (this.#items.length === 0) return undefined;
    const { key, priority } = this.#items[0];
    return { key, priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    if (this.#items.length === 0) return undefined;
    const { key, priority } = this.#items[0];
    this.#removeAt(0);
    return { key, priority };
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    this.#checkKey(key);
    return this.#index.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    this.#checkKey(key);
    const pos = this.#index.get(key);
    return pos === undefined ? undefined : this.#items[pos].priority;
  }

  /**
   * Lowers the priority of a held key.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority; must not exceed the current one.
   * @returns {void}
   */
  decreaseKey(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    const pos = this.#index.get(key);
    if (pos === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const current = this.#items[pos].priority;
    if (priority > current) throw new RangeError(`priority must not increase for "${key}"`);
    this.#items[pos].priority = priority;
    this.#siftUp(pos);
  }

  /**
   * Sets the priority of a held key in either direction.
   * @param {string} key Key to re-prioritise.
   * @param {number} priority New priority.
   * @returns {void}
   */
  setPriority(key, priority) {
    this.#checkKey(key);
    this.#checkPriority(priority);
    const pos = this.#index.get(key);
    if (pos === undefined) throw new ReferenceError(`unknown key: "${key}"`);
    const current = this.#items[pos].priority;
    this.#items[pos].priority = priority;
    if (priority < current) this.#siftUp(pos);
    else if (priority > current) this.#siftDown(pos);
  }

  /**
   * Removes a held key.
   * @param {string} key Key to remove.
   * @returns {boolean} True when an entry was removed.
   */
  remove(key) {
    this.#checkKey(key);
    const pos = this.#index.get(key);
    if (pos === undefined) return false;
    this.#removeAt(pos);
    return true;
  }

  /**
   * Empties the heap.
   * @returns {Array<{key: string, priority: number}>} Every entry in pop order.
   */
  drain() {
    const result = [];
    let next;
    while ((next = this.pop()) !== undefined) result.push(next);
    return result;
  }
}
"}

