 * Single-source shortest paths over a weighted directed graph, driven by the
 * indexed heap so a shorter route to a queued node lowers its priority in
 * place instead of enqueueing a duplicate.
 */
import { IndexedHeap } from './heap.js';

/**
 * Checks whether a value is a plain, non-array object.
 * @param {unknown} value Value to check.
 * @returns {boolean} True when the value qualifies.
 */
function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Validates a graph and returns its node ids.
 * @param {unknown} graph Weighted directed graph.
 * @returns {string[]} Node ids in the graph.
 */
function validateGraph(graph) {
  if (!isPlainObject(graph)) throw new TypeError('graph must be an object');
  const nodes = Object.keys(graph);
  const nodeSet = new Set(nodes);
  for (const node of nodes) {
    const edges = graph[node];
    if (!isPlainObject(edges)) throw new TypeError(`edge map for node "${node}" must be an object`);
    for (const [target, weight] of Object.entries(edges)) {
      if (!nodeSet.has(target)) throw new ReferenceError(`unknown node: "${target}"`);
      if (typeof weight !== 'number' || !Number.isFinite(weight) || weight <= 0) {
        throw new RangeError(`weight must be positive: "${node}" -> "${target}"`);
      }
    }
  }
  return nodes;
}

/**
 * Computes the distance and predecessor of every node from one source.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @returns {{dist: Record<string, number>, prev: Record<string, string | null>}} Distances and predecessors.
 */
export function shortestPaths(graph, source) {
  const nodes = validateGraph(graph);
  if (typeof source !== 'string') throw new TypeError('source must be a string');
  if (!nodes.includes(source)) throw new ReferenceError(`unknown node: "${source}"`);

  /** @type {Record<string, number>} */
  const dist = {};
  /** @type {Record<string, string | null>} */
  const prev = {};
  for (const node of nodes) {
    dist[node] = Number.POSITIVE_INFINITY;
    prev[node] = null;
  }
  dist[source] = 0;

  const heap = new IndexedHeap();
  for (const node of nodes) heap.push(node, dist[node]);
  heap.decreaseKey(source, 0);

  const settled = new Set();

  while (heap.size > 0) {
    const { key: node, priority } = heap.pop();
    if (settled.has(node)) continue;
    settled.add(node);
    if (priority === Number.POSITIVE_INFINITY) continue;
    const edges = graph[node];
    for (const target of Object.keys(edges).sort()) {
      const weight = edges[target];
      if (settled.has(target)) continue;
      const candidate = dist[node] + weight;
      if (candidate < dist[target] || (candidate === dist[target] && (prev[target] === null || node < prev[target]))) {
        if (candidate < dist[target]) {
          dist[target] = candidate;
          prev[target] = node;
          if (heap.has(target)) heap.decreaseKey(target, candidate);
        } else if (prev[target] === null || node < prev[target]) {
          prev[target] = node;
        }
      }
    }
  }

  return { dist, prev };
}

/**
 * Finds one shortest route between two nodes.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @param {string} target Node to reach.
 * @returns {{distance: number, path: string[]} | null} Route, or null when unreachable.
 */
export function shortestPath(graph, source, target) {
  const nodes = validateGraph(graph);
  if (typeof source !== 'string') throw new TypeError('source must be a string');
  if (!nodes.includes(source)) throw new ReferenceError(`unknown node: "${source}"`);
  if (!nodes.includes(target)) throw new ReferenceError(`unknown node: "${target}"`);

  const { dist, prev } = shortestPaths(graph, source);
  if (dist[target] === Number.POSITIVE_INFINITY) return null;

  const path = [];
  let node = target;
  while (node !== null) {
    path.push(node);
    if (node === source) break;
    node = prev[node];
  }
  path.reverse();

  return { distance: dist[target], path };
}
